import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def paired_views(ctx):
    label = int(ctx.index) % 2
    center = torch.zeros(4)
    center[label] = 1.0
    clean = center + 0.05 * torch.randn(4, generator=ctx.rng.torch)
    adversarial = clean + 0.1 * torch.randn(4, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(torch.stack((clean, adversarial))), "targets": label}
dataset = synth.Spec("trades-paired-views", generator=paired_views, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PairedClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        return {"clean_logits": self.network(inputs[:, 0]), "adversarial_logits": self.network(inputs[:, 1])}
trainer = Trainer(PairedClassifier(), train, recipe="structured-objective", recipe_config={"loss": "trades", "loss_kwargs": {"beta": 1.0}, "bindings": {"logits_or_prediction": {"output": "clean_logits"}, "adversarial_logits": {"output": "adversarial_logits"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
